"""Render benchmarks/results/*.json into docs/benchmarks.md (generated; do not edit by hand).

    python benchmarks/report.py
"""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RES = ROOT / "benchmarks" / "results"


def main() -> None:
    L = ["# Benchmarks (generated)", "", "Generated by `python benchmarks/report.py` from `benchmarks/results/*.json`. "
         "Re-run the three benchmark scripts to regenerate. Public data only (1000 Genomes phase 3; PGS Catalog; "
         "the public 23andMe genomes bundled with ClawBio).", ""]
    a = json.loads((RES / "ancestry_benchmark.json").read_text())
    s = a["summary"]
    L += ["## Reference placement (leave-one-out)", "",
          f"Seed {a['seed']}; {a['bootstrap']} marker bootstraps; K = {a['k_pcs']} PCs; cloud quantile "
          f"{a['cloud_quantile']}; {a['ref_per_group']} reference samples per core group; "
          f"{a['n_jobs']} placements.", "",
          "### Core populations (all projection sites)", "", "| Group | n | Resolved, correct | Resolved, wrong | "
          "Intermediate | Unstable |", "|---|---|---|---|---|---|"]
    for g, v in s["core"].items():
        L.append(f"| {g} | {v['n']} | {v['resolved_correct']} | {v['resolved_wrong']} | {v['intermediate']} | "
                 f"{v['unstable']} |")
    L += ["", "### Admixed populations (never used to define axes)", "",
          "| Population | n | Outcomes | Median max admixture component |", "|---|---|---|---|"]
    for p, v in s["admixed"].items():
        oc = ", ".join(f"{k} {n}" for k, n in sorted(v["outcomes"].items()))
        L.append(f"| {p} | {v['n']} | {oc} | {v['median_max_admixture_component']} |")
    L += ["", "### Sparse inputs (random site subsets of held-out core samples)", "",
          "| Sites | n | Resolved | Resolved correct | Resolved wrong | Median stability |",
          "|---|---|---|---|---|---|"]
    for n, v in s["sparsity"].items():
        L.append(f"| {n} | {v['n']} | {v['resolved']} | {v['resolved_correct']} | {v['resolved_wrong']} | "
                 f"{v['median_stability']} |")
    b = json.loads((RES / "scoreability_benchmark.json").read_text())
    L += ["", "## Scoreability (masking experiments)", "",
          f"Scores {', '.join(b['scores'])}; five core groups; masks: simulated consumer array, random retention "
          "(10 replicates per level), removal of the largest weights. Pooled consequences by r(full, reduced):", "",
          "| r band | masks | median abs. percentile error | 95th pct abs. error (median) | same decile | "
          "top-decile recovered | variants retained (range) |", "|---|---|---|---|---|---|---|"]
    for t in b["r_consequence_table"]:
        lo, hi = t["r_band"]
        fr = t["fraction_variants_range"]
        L.append(f"| {lo:.2f}-{hi:.2f} | {t['n']} | {t['pct_err_median']} | {t['pct_err_p95_median']} | "
                 f"{t['same_decile_median']} | {t['top_decile_recovered_median']} | {fr[0]:.2f}-{fr[1]:.2f} |")
    L += ["", "Simulated consumer array (chip content of the public 23andMe genomes, palindromic SNPs excluded):", "",
          "| Score | Group | Variants retained | abs-weight retained | r | Spearman | ICC(A,1) | Bland-Altman bias "
          "[95% LoA] (z) | 95th pct abs. error | same decile |", "|---|---|---|---|---|---|---|---|---|---|"]
    for r in b["array_mask"]:
        ba = r["bland_altman_z"]
        L.append(f"| {r['pgs_id']} | {r['group']} | {r['fraction_variants']} | {r['fraction_abs_weight']} | "
                 f"{r['r']} | {r['spearman']} | {r['icc_a1_standardized']} | {ba['bias']} [{ba['loa95'][0]}, "
                 f"{ba['loa95'][1]}] | {r['pct_err_p95']} | {r['same_decile']} |")
    L += ["", "### Known reference samples: the same score in different 1000 Genomes groups", "",
          "Mean in EUR standard deviations, SD ratio, and the share of each group above the EUR 90th percentile. "
          "A EUR-based percentile would place many non-EUR people in the 'top 10%' (or bottom) for reasons of "
          "allele-frequency and LD differences, not risk: the reason PRSGuard only uses a reference matched to "
          "the person's placement.", "",
          "| Score | Group | n | Mean (EUR SD) | SD ratio | Share above EUR p90 |", "|---|---|---|---|---|---|"]
    for r in b["group_distributions"]:
        L.append(f"| {r['pgs_id']} | {r['group']} | {r['n']} | {r['mean_in_eur_sd']} | {r['sd_ratio_to_eur']} | "
                 f"{r['share_above_eur_p90']} |")
    h = json.loads((RES / "harmonisation_benchmark.json").read_text())
    L += ["", "## Build agreement and allele reconciliation (real public files)", "",
          "| File | Resolved build | GRCh37 anchor agreement | GRCh38 anchor agreement | Anchors | "
          "Allele-mismatch fraction by score |", "|---|---|---|---|---|---|"]
    for r in h["files"]:
        mm = ", ".join(f"{k} {v}" for k, v in r["mismatch"].items())
        L.append(f"| {r['file']} | {r['build']} | {r['grch37_agreement']} | {r['grch38_agreement']} | "
                 f"{r['anchors_checked']} | {mm} |")
    L += ["", "Perturbation (case B genome, a fraction of calls replaced by a base outside the site's alleles):", "",
          "| Corrupted calls | Detected mismatch fraction by score |", "|---|---|"]
    for p in h["perturbation"]:
        L.append(f"| {p['corrupted_fraction']} | " + ", ".join(f"{k} {v}" for k, v in p["mismatch"].items()) + " |")
    (ROOT / "docs" / "benchmarks.md").write_text("\n".join(L) + "\n")
    print("wrote docs/benchmarks.md")


if __name__ == "__main__":
    main()
